import {gameDataVersion,lastVerified,sources,paths,builds,skills,statNames,gearSlots} from './data/game.js';
import {validateGame} from './data/validation.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='rose-build-planner-saves-v1';let saves=[];try{saves=JSON.parse(localStorage.getItem(key)||'[]')}catch{};
let state={path:'Muse',job:'Cleric',build:'cleric-0',level:137,tab:'BUILD',stats:Object.fromEntries(statNames.map(x=>[x,0])),ranks:{},gear:{},notes:'',query:'',wizard:''};
function current(){return builds.find(b=>b.id===state.build)||builds[0]};
function persist(){localStorage.setItem(key,JSON.stringify(saves))}
function loadConfig(c){if(!c||!builds.some(b=>b.id===c.build))return;state={...state,...c,level:Math.max(10,Math.min(250,Number(c.level)||10)),tab:'BUILD'};render()}
try{const encoded=new URL(location.href).searchParams.get('build');if(encoded){const json=decodeURIComponent(escape(atob(encoded.replace(/-/g,'+').replace(/_/g,'/'))));loadConfig(JSON.parse(json))}}catch{}
function setJob(job){state.job=job;state.path=Object.keys(paths).find(p=>paths[p].includes(job));state.build=builds.find(b=>b.job===job).id;state.ranks={};render()}
function hdr(){return `<header><div class="top"><div><div class="brand">✦ ROSE BUILD PLANNER</div><div class="tiny">Global · Rednim Games · dane ${esc(lastVerified)}</div></div><span class="tiny">v${esc(gameDataVersion)}</span></div></header>`}
function sidebar(){return `<aside class="panel side"><h2>Choose your class</h2><div class="chooser">${Object.keys(paths).map(p=>`<button class="pick ${state.path===p?'active':''}" data-path="${p}">${p}</button>`).join('')}</div><div class="group" style="margin-top:18px"><label>Klasa końcowa</label><div class="chooser">${paths[state.path].map(j=>`<button class="pick ${state.job===j?'active':''}" data-job="${j}">${j}</button>`).join('')}</div></div><div class="group"><label for="build">Archetyp</label><select id="build">${builds.filter(b=>b.job===state.job).map(b=>`<option value="${b.id}" ${state.build===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></div><div class="group"><label for="search">Szukaj klasy, buildu, skilla, broni</label><input id="search" type="search" placeholder="np. Ice Dragon" value="${esc(state.query)}"></div><div class="group"><label for="wizard">Kreator: co chcesz robić?</label><select id="wizard"><option value="">Wybierz cel</option>${['solo','party','dungeon','boss','farming','support','crafting','ranged','summon'].map(x=>`<option ${state.wizard===x?'selected':''}>${x}</option>`).join('')}</select></div>${state.wizard?`<div class="hint">Pasujące: ${builds.filter(b=>b.tags.includes(state.wizard)).map(b=>`<button class="btn" data-goto="${b.id}">${esc(b.job)} · ${esc(b.name)}</button>`).join(' ')||'Brak potwierdzonych wyników'}</div>`:''}<div class="footer">Lokalne zapisy nie wymagają konta. Udostępniony link zawiera ustawienia buildu.</div></aside>`}
function level(){return `<div class="card"><div class="headline"><h2>Level ${state.level}</h2><span class="pill">10–250</span></div><div class="levelrange"><input id="range" type="range" min="10" max="250" value="${state.level}" aria-label="Poziom"><input id="level" type="number" min="10" max="250" value="${state.level}" aria-label="Dokładny poziom"></div><div class="timeline">${Array.from({length:25},(_,i)=>10+i*10).map(n=>`<button class="step" data-level="${n}">${n}</button>`).join('')}</div><div class="hint">Pula punktów i instrukcja „następne SP” — BRAK POTWIERDZONYCH DANYCH. Nie wyliczamy rozkładu z nieznanej mechaniki.</div></div>`}
function overview(b){return `<div class="card"><div class="headline"><div><h2>${esc(b.job)} · ${esc(b.name)}</h2><div class="muted">${esc(state.path)} → ${esc(b.job)} · ${esc(b.weapon)}</div></div><span class="pill">🟡 ${esc(b.status)}</span></div><p class="note">${esc(b.note)}</p><div class="twocol"><div><h3>Purpose</h3><p>${esc(b.purpose)}</p><h3>Recommended Weapon</h3><p>${esc(b.weapon)} — wariant archetypu, szczegóły sprzętu do weryfikacji.</p></div><div><h3>Strengths / Weaknesses</h3><p class="muted">BRAK POTWIERDZONYCH DANYCH porównawczych.</p><h3>Gameplay / Rotation</h3><p class="muted">BRAK POTWIERDZONYCH DANYCH o kompletnej rotacji.</p></div></div><div class="hint">Last verified: ${b.lastVerified}. Potwierdzenie obejmuje wymienione niżej fakty źródłowe, nie kompletny build.</div></div><div class="card"><h2>Compare Builds</h2>${builds.filter(x=>x.job===b.job).map(x=>`<div class="row"><span>${esc(x.name)}</span><small>${esc(x.purpose)}</small></div>`).join('')}<p class="hint">Damage, Healing, Solo, Party, Boss, AoE, Survivability, Cost i Difficulty: brak pomiarów; opis celu nie jest oceną wydajności.</p></div>`}
function statPane(){let used=Object.values(state.stats).reduce((a,b)=>a+b,0);return `<div class="card"><h2>Stat calculator</h2><p class="note">Available Points: BRAK POTWIERDZONYCH DANYCH · Used Points: ${used} · Remaining Points: nieznane. Wpisujesz przydzielone punkty, nie końcowe wartości postaci.</p><div class="statgrid">${statNames.map(x=>`<div class="stat"><label for="stat-${x}">${x}</label><input id="stat-${x}" data-stat="${x}" type="number" min="0" step="1" value="${state.stats[x]||0}"></div>`).join('')}</div><p class="hint">Zalecenia do dowolnego levelu wymagają potwierdzonej puli statów i progów dla każdego poziomu. Kolory zgodności pojawią się po dodaniu tych danych.</p><button class="btn" data-action="reset-stats">Reset statów</button></div>`}
function skillPane(){const listed=skills.filter(s=>s.job===state.job);const spent=Object.entries(state.ranks).reduce((a,[id,n])=>a+n*(skills.find(x=>x.id===id)?.spCost||0),0);return `<div class="card"><h2>Skill tree · ${esc(state.job)}</h2><p class="note">Available SP: BRAK POTWIERDZONYCH DANYCH · Used SP: ${Object.keys(state.ranks).length?`${spent} (część kosztów nieznana)`:'0'} · Remaining SP: nieznane.</p>${listed.length?`<div class="skills">${listed.map(s=>`<div class="skill"><strong>${esc(s.name)}</strong><p>${esc(s.effect)}</p><div class="meta">${esc(s.type)} · Max rank ${s.maxRank??'nieznany'} · SP/rank, wymagany level, prerequisite i MP: brak potwierdzonych danych</div><div class="controls"><button disabled title="Brak zweryfikowanych wymagań">−</button><span>${state.ranks[s.id]||0} / ${s.maxRank??'?'}</span><button disabled title="Brak zweryfikowanych wymagań">+</button><span class="hint">Zablokowane do weryfikacji drzewa</span></div></div>`).join('')}</div>`:'<div class="empty">BRAK POTWIERDZONYCH DANYCH o aktualnym drzewku tej klasy.</div>'}<p class="hint">Nie można dodać skilla bez znanego kosztu, wymaganego levelu i wszystkich prerequisite. Wyszukiwarka obejmuje potwierdzone nazwy z patchy.</p><button class="btn" data-action="reset-skills">Reset skilli</button></div>`}
function gearPane(){return `<div class="card"><h2>Equipment</h2><p class="note">Konkretnych itemów, Unique, gemów, opcji i kolejności statów nie przypisano bez aktualnego potwierdzenia.</p><div class="rows">${gearSlots.map(slot=>`<div class="group"><label for="gear-${slot}">${slot} · ⭐ Unique: niepotwierdzone</label><input id="gear-${slot}" data-gear="${slot}" value="${esc(state.gear[slot]||'')}" placeholder="Własny przedmiot / opcje"></div>`).join('')}</div><p class="hint">Leveling / Cheap · Mid Game · Endgame: BRAK POTWIERDZONYCH DANYCH. Własne wpisy nie stają się rekomendacjami.</p></div>`}
function sourcesPane(b){return `<div class="card sources"><h2>Sources · Last verified ${esc(b.lastVerified)}</h2>${b.sourceKeys.map(k=>`<a target="_blank" rel="noopener" href="${sources[k]}">${esc(k==='classes'?'Aktualna dyskusja o strukturze klas':k==='champ'?'Oficjalny patch Champion 11.09.2026':'Oficjalny patch Summons / Scout 13.09.2026')} ↗</a>`).join('')}<p class="hint">Status 🟡 PARTIALLY VERIFIED oznacza, że potwierdzono tylko fakty wymienione w aplikacji. Brak pełnych tabel statów/SP, prerequisite i danych itemów. Walidator nie nadaje całemu buildowi statusu VERIFIED.</p></div>`}
function savePane(){let b=current(),v=validateGame({build:b,level:state.level,stats:state.stats,skills:state.ranks,catalog:skills});return `<div class="card"><h2>Mój build</h2><div class="group"><label for="notes">Notatki</label><textarea id="notes" placeholder="Własne uwagi do postaci">${esc(state.notes)}</textarea></div><div class="actions"><button class="btn primary" data-action="save">Zapisz lokalnie</button><button class="btn" data-action="share">Share Build</button><button class="btn" data-action="reset-all">Reset konfiguracji</button></div><p class="hint">Status walidacji: ${esc(v.status)}. ${v.errors.length?esc(v.errors.join(' · ')):'Pula punktów nie jest potwierdzona.'}</p><div id="feedback" class="hint" role="status"></div><h3>Zapisane konfiguracje</h3>${saves.length?saves.map((c,i)=>`<div class="row"><button class="btn" data-load="${i}">${esc(c.name)} · lvl ${c.level}</button><button class="btn" data-delete="${i}">Usuń</button></div>`).join(''):'<p class="muted">Brak zapisów na tym urządzeniu.</p>'}</div>`}
function searchPane(){let q=state.query.toLowerCase().trim();if(!q)return '';let bs=builds.filter(b=>`${b.job} ${b.name} ${b.weapon}`.toLowerCase().includes(q)),ss=skills.filter(s=>`${s.name} ${s.job} ${s.effect}`.toLowerCase().includes(q));return `<div class="card"><h2>Wyniki wyszukiwania</h2>${bs.map(b=>`<button class="btn" data-goto="${b.id}">${esc(b.job)} · ${esc(b.name)}</button>`).join(' ')}${ss.map(s=>`<button class="btn" data-job="${s.job}">${esc(s.name)} · ${esc(s.job)}</button>`).join(' ')}${!bs.length&&!ss.length?'<p class="muted">Nie znaleziono w potwierdzonych danych.</p>':''}</div>`}
function render(){let b=current();$('#app').innerHTML=hdr()+`<main class="shell"><div class="intro"><div><h1>Build planner</h1><p>Visitor → ${esc(state.path)} → ${esc(state.job)} · krok po kroku, gdy dane są potwierdzone</p></div></div><div class="grid">${sidebar()}<section class="content">${searchPane()}${level()}<nav class="tabs" aria-label="Sekcje">${['BUILD','STATS','SKILLS','LEVELING','GEAR','ROTATION','SOURCES','SAVE'].map(t=>`<button class="tab ${state.tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</nav>${state.tab==='BUILD'?overview(b):state.tab==='STATS'?statPane():state.tab==='SKILLS'?skillPane():state.tab==='LEVELING'?`<div class="card"><h2>Level ${state.level} · progresja</h2><p class="note">BRAK POTWIERDZONYCH DANYCH: dokładny przydział STR / DEX / INT / CON / CHA / SEN i SP do poziomu ${state.level}.</p><p>Wybierz dowolny level 10–250 u góry. Zapisz własne punkty w zakładkach STATS i SKILLS.</p><p class="hint">Zmiana klasy na lvl 10 i 100 wymaga pełnego potwierdzenia w źródłach Globalu.</p></div>`:state.tab==='GEAR'?gearPane():state.tab==='ROTATION'?`<div class="card"><h2>Gameplay · ${esc(b.name)}</h2><p class="note">${esc(b.note)}</p><p>Skill rotation i priorytety na każdym poziomie: BRAK POTWIERDZONYCH DANYCH.</p>${state.job==='Cleric'?'<p>Patch 13.09: Earth Elemental — area taunt; Fire Elemental — area burn; Ice Dragon — Frost Nova, 25% slow. Pozostałe parametry summonów wymagają weryfikacji.</p>':''}</div>`:state.tab==='SOURCES'?sourcesPane(b):savePane()}</section></div></main>`;bind()}
function bind(){document.querySelectorAll('[data-path]').forEach(el=>el.onclick=()=>{state.path=el.dataset.path;setJob(paths[state.path][0])});document.querySelectorAll('[data-job]').forEach(el=>el.onclick=()=>setJob(el.dataset.job));document.querySelectorAll('[data-goto]').forEach(el=>el.onclick=()=>{state.build=el.dataset.goto;setJob(builds.find(b=>b.id===state.build).job);state.build=el.dataset.goto;render()});$('#build').onchange=e=>{state.build=e.target.value;render()};document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{state.tab=el.dataset.tab;render()});$('#search').onchange=e=>{state.query=e.target.value;render()};$('#wizard').onchange=e=>{state.wizard=e.target.value;render()};const setLevel=v=>{state.level=Math.max(10,Math.min(250,Number(v)||10));render()};$('#range').oninput=e=>setLevel(e.target.value);$('#level').onchange=e=>setLevel(e.target.value);document.querySelectorAll('[data-level]').forEach(el=>el.onclick=()=>setLevel(el.dataset.level));document.querySelectorAll('[data-stat]').forEach(el=>el.onchange=e=>{state.stats[el.dataset.stat]=Math.max(0,Math.floor(Number(e.target.value)||0));render()});document.querySelectorAll('[data-gear]').forEach(el=>el.onchange=e=>state.gear[el.dataset.gear]=e.target.value);$('#notes')?.addEventListener('change',e=>state.notes=e.target.value);document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-load]').forEach(el=>el.onclick=()=>loadConfig(saves[Number(el.dataset.load)]));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{saves.splice(Number(el.dataset.delete),1);persist();render()})}
function config(){return {path:state.path,job:state.job,build:state.build,level:state.level,stats:state.stats,ranks:state.ranks,gear:state.gear,notes:$('#notes')?.value??state.notes}}
async function action(a){if(a==='reset-stats')state.stats=Object.fromEntries(statNames.map(x=>[x,0]));if(a==='reset-skills')state.ranks={};if(a==='reset-all'){state.stats=Object.fromEntries(statNames.map(x=>[x,0]));state.ranks={};state.gear={};state.notes=''}if(a==='save'){let c=config();c.name=prompt('Nazwa buildu',`Mój ${current().name}`)?.trim();if(!c.name)return;saves.push(c);persist()}if(a==='share'){let encoded=btoa(unescape(encodeURIComponent(JSON.stringify(config())))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');let url=new URL(location.href);url.searchParams.set('build',encoded);try{await navigator.clipboard.writeText(url.href);$('#feedback').textContent='Link skopiowany.'}catch{$('#feedback').textContent=url.href}return}render()}
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
